/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.util.Map;
import java.util.UUID;

import org.jose4j.jwk.RsaJsonWebKey;
import org.jose4j.jwk.RsaJwkGenerator;
import org.jose4j.jws.AlgorithmIdentifiers;
import org.jose4j.jws.JsonWebSignature;
import org.jose4j.jwt.JwtClaims;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import io.restassured.specification.RequestSpecification;
import net.civeira.phylax.features.oauth.tokensecurity.application.DpopProofVerifier;
import net.civeira.phylax.features.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

/**
 * DPoP (RFC 9449, task 3.6): a valid proof binds the tokens to its key; a replayed proof, another
 * URL, a missing proof for a client that requires it, a bound token sent as Bearer, or a proof of
 * another key are refused; the refresh keeps the binding.
 */
@QuarkusTest
class DpopFlowTest extends OidcIntegrationTestBase {

  private static final String BASE = "/oauth/openid/" + OidcTestFixtures.TENANT;

  private RsaJsonWebKey key;
  private String issuer;

  @BeforeEach
  void setUp() throws Exception {
    key = RsaJwkGenerator.generateJwk(2048);
    issuer =
        RestAssured.get(BASE + "/.well-known/openid-configuration").jsonPath().getString("issuer");
  }

  private static String proof(RsaJsonWebKey with, String method, String url, String accessToken)
      throws Exception {
    JwtClaims claims = new JwtClaims();
    claims.setJwtId(UUID.randomUUID().toString());
    claims.setStringClaim("htm", method);
    claims.setStringClaim("htu", url);
    claims.setIssuedAtToNow();
    if (accessToken != null) {
      claims.setStringClaim("ath", DpopProofVerifier.hash(accessToken));
    }
    JsonWebSignature jws = new JsonWebSignature();
    jws.setHeader("typ", "dpop+jwt");
    jws.setAlgorithmHeaderValue(AlgorithmIdentifiers.RSA_USING_SHA256);
    jws.setJwkHeader(with);
    jws.setPayload(claims.toJson());
    jws.setKey(with.getPrivateKey());
    return jws.getCompactSerialization();
  }

  private static RequestSpecification asClient() {
    return RestAssured.given().auth().preemptive()
        .basic(OidcTestFixtures.CLIENT_ID, OidcTestFixtures.CLIENT_SECRET)
        .contentType(ContentType.URLENC);
  }

  private Response password(String proofHeader) {
    RequestSpecification spec = asClient().formParam("grant_type", "password")
        .formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("scope", "openid");
    if (proofHeader != null) {
      spec = spec.header("DPoP", proofHeader);
    }
    return spec.post(BASE + "/token");
  }

  private String token() {
    return issuer + "/token";
  }

  private void active(String accessToken) {
    String jti = String.valueOf(decodeToken(accessToken).get("jti"));
    tokenLookupGateway.storeByJti(jti, TokenIntrospectionResult.builder().active(true)
        .clientId(OidcTestFixtures.CLIENT_ID).jti(jti).build());
  }

  @Test
  void proof_bindsTheToken_toItsKey() throws Exception {
    Response issued = password(proof(key, "POST", token(), null));

    Assertions.assertEquals(200, issued.statusCode(), issued.getBody().asString());
    Assertions.assertEquals("DPoP", issued.jsonPath().getString("token_type"));
    Object cnf = decodeToken(issued.jsonPath().getString("access_token")).get("cnf");
    Assertions.assertEquals(key.calculateBase64urlEncodedThumbprint("SHA-256"),
        ((Map<?, ?>) cnf).get("jkt"));
  }

  @Test
  void replayedProof_orAnotherUrl_isRefused() throws Exception {
    String proof = proof(key, "POST", token(), null);
    Assertions.assertEquals(200, password(proof).statusCode());
    Response replay = password(proof);
    Assertions.assertEquals(400, replay.statusCode());
    Assertions.assertEquals("invalid_dpop_proof", replay.jsonPath().getString("error"));

    Assertions.assertEquals(400,
        password(proof(key, "POST", issuer + "/introspect", null)).statusCode());
    Assertions.assertEquals(400, password(proof(key, "GET", token(), null)).statusCode());
  }

  @Test
  void clientRequiringDpop_needsAProof() throws Exception {
    clientStoreGateway.customize(b -> b.dpopBoundAccessTokens(true));
    Assertions.assertEquals(400, password(null).statusCode());
    Assertions.assertEquals(200, password(proof(key, "POST", token(), null)).statusCode());
  }

  @Test
  void boundToken_atUserinfo_needsAProofOfTheSameKey() throws Exception {
    String access =
        password(proof(key, "POST", token(), null)).jsonPath().getString("access_token");
    active(access);
    String userinfo = issuer + "/userinfo";

    Assertions.assertEquals(401,
        RestAssured.given().auth().oauth2(access).get(BASE + "/userinfo").statusCode(),
        "A bound token is not a bearer token");
    Assertions.assertEquals(200, RestAssured.given().header("Authorization", "DPoP " + access)
        .header("DPoP", proof(key, "GET", userinfo, access)).get(BASE + "/userinfo").statusCode());
    Assertions.assertEquals(401,
        RestAssured.given().header("Authorization", "DPoP " + access)
            .header("DPoP", proof(RsaJwkGenerator.generateJwk(2048), "GET", userinfo, access))
            .get(BASE + "/userinfo").statusCode());
  }

  @Test
  void boundRefresh_onlyWithTheSameKey() throws Exception {
    String refresh =
        password(proof(key, "POST", token(), null)).jsonPath().getString("refresh_token");

    Assertions.assertEquals(400, asClient().formParam("grant_type", "refresh_token")
        .formParam("refresh_token", refresh).post(BASE + "/token").statusCode());
    Assertions.assertEquals(400,
        asClient().header("DPoP", proof(RsaJwkGenerator.generateJwk(2048), "POST", token(), null))
            .formParam("grant_type", "refresh_token").formParam("refresh_token", refresh)
            .post(BASE + "/token").statusCode());
    Response rotated = asClient().header("DPoP", proof(key, "POST", token(), null))
        .formParam("grant_type", "refresh_token").formParam("refresh_token", refresh)
        .post(BASE + "/token");
    Assertions.assertEquals(200, rotated.statusCode(), rotated.getBody().asString());
    Assertions.assertEquals("DPoP", rotated.jsonPath().getString("token_type"));
  }

  @Test
  void introspection_reportsTheBinding() throws Exception {
    String access =
        password(proof(key, "POST", token(), null)).jsonPath().getString("access_token");
    active(access);
    Response introspection = asClient().formParam("token", access).post(BASE + "/introspect");
    Assertions.assertEquals(200, introspection.statusCode());
    Assertions.assertTrue(introspection.jsonPath().getBoolean("active"));
    Assertions.assertEquals(key.calculateBase64urlEncodedThumbprint("SHA-256"),
        introspection.jsonPath().getString("cnf.jkt"));
  }
}
